{
  "expo": {
    "name": "IngreDish",
    "slug": "ingredish",
    "version": "1.0.0",
    "orientation": "portrait",
    "icon": "./assets/images/icon.png",
    "scheme": "ingredish",
    "userInterfaceStyle": "automatic",
    "newArchEnabled": true,
    "splash": {
      "image": "./assets/images/splash.png",
      "resizeMode": "contain",
      "backgroundColor": "#ffffff"
    },
    "assetBundlePatterns": [
      "**/*"
    ],
    "ios": {
      "supportsTablet": true,
      "bundleIdentifier": "com.ingredish.app",
      "infoPlist": {
        "NSAppTransportSecurity": {
          "NSAllowsArbitraryLoads": true,
          "NSExceptionDomains": {
            "15.235.185.245": {
              "NSExceptionAllowsInsecureHTTPLoads": true,
              "NSExceptionMinimumTLSVersion": "1.0",
              "NSIncludesSubdomains": true
            }
          }
        }
      }
    },
    "android": {
      "adaptiveIcon": {
        "foregroundImage": "./assets/images/icon.png",
        "backgroundColor": "#ffffff"
      },
      "package": "com.ingredish.app",
      "usesCleartextTraffic": true,
      "permissions": [
        "android.permission.INTERNET",
        "android.permission.ACCESS_NETWORK_STATE",
        "android.permission.ACCESS_WIFI_STATE"
      ],
      "networkSecurityConfig": {
        "cleartextTrafficPermitted": true,
        "domain-config": [
          {
            "domain": "15.235.185.245",
            "cleartextTrafficPermitted": true
          }
        ]
      }
    },
    "web": {
      "bundler": "metro",
      "output": "static",
      "favicon": "./assets/images/favicon.png"
    },
    "plugins": [
      "expo-router"
    ],
    "experiments": {
      "typedRoutes": true
    },
    "extra": {
      "router": {
        "origin": false
      },
      "eas": {
        "projectId": "0c52d48e-196b-4edf-8da6-6d17492540b4"
      }
    }
  }
}

import React from 'react';
import { View, Text, TouchableOpacity, StyleSheet } from 'react-native';
import { useRouter } from 'expo-router';

export default function NotFoundScreen() {
  const router = useRouter();

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Oops! Page not found</Text>
      <Text style={styles.message}>
        The page you're looking for doesn't exist.
      </Text>
      <TouchableOpacity 
        style={styles.button}
        onPress={() => router.replace('/(root)/welcomepage')}
      >
        <Text style={styles.buttonText}>Go Home</Text>
      </TouchableOpacity>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    padding: 20,
    backgroundColor: '#fff',
  },
  title: {
    fontSize: 24,
    fontWeight: 'bold',
    marginBottom: 10,
    textAlign: 'center',
  },
  message: {
    fontSize: 16,
    textAlign: 'center',
    marginBottom: 30,
    color: '#666',
  },
  button: {
    backgroundColor: '#007AFF',
    paddingHorizontal: 30,
    paddingVertical: 15,
    borderRadius: 8,
  },
  buttonText: {
    color: 'white',
    fontSize: 16,
    fontWeight: '600',
  },
});

import React from 'react';
import { Stack } from 'expo-router';
import { RecipeProvider } from '../contexts/RecipeContext';
import './globals.css';

export default function RootLayout() {
  return (
    <RecipeProvider>
      <Stack
        screenOptions={{
          headerShown: false,
        }}
      >
        <Stack.Screen name="(root)" options={{ headerShown: false }} />
        <Stack.Screen name="home" options={{ headerShown: false }} />
        <Stack.Screen name="recipe-result" options={{ headerShown: false }} />
        <Stack.Screen name="*" options={{ headerShown: false }} />
      </Stack>
    </RecipeProvider>
  );
}

import React from 'react';
import { Stack } from 'expo-router';
import { RecipeProvider } from '../contexts/RecipeContext';
import './globals.css';

export default function RootLayout() {
  return (
    <RecipeProvider>
      <Stack
        screenOptions={{
          headerShown: false,
          // Add better animation and navigation options for standalone builds
          animation: 'slide_from_right',
          animationDuration: 200,
        }}
      >
        <Stack.Screen 
          name="index" 
          options={{ 
            headerShown: false,
            // Ensure this is treated as the initial route
            initialParams: {}
          }} 
        />
        <Stack.Screen 
          name="(root)" 
          options={{ 
            headerShown: false,
            // Ensure proper nesting
            presentation: 'card'
          }} 
        />
        <Stack.Screen 
          name="home" 
          options={{ 
            headerShown: false,
            title: 'Home'
          }} 
        />
        <Stack.Screen 
          name="recipe-result" 
          options={{ 
            headerShown: false,
            title: 'Recipe Result',
            // Allow going back
            gestureEnabled: true
          }} 
        />
        {/* Catch-all route for unmatched paths */}
        <Stack.Screen 
          name="+not-found" 
          options={{ 
            headerShown: false,
            title: 'Not Found'
          }} 
        />
      </Stack>
    </RecipeProvider>
  );
}

import axios from 'axios';

const endpoint = "http://15.235.185.245/recipe/";

const headers = {
    "Content-Type": "application/json",
};

// Configure axios for better APK compatibility
const apiClient = axios.create({
    baseURL: endpoint,
    timeout: 30000, // 30 second timeout
    headers: headers,
});

interface RecipeParams {
    diet: string;
    type: string;
    difficulty: string;
    ingredients: string;
}

export async function generateRecipe(params: RecipeParams) {
    try {
        console.log("Sending request to:", endpoint);
        console.log("Request params:", params);

        const response = await apiClient.post("", params);

        console.log("Response received:", response.status);
        console.log("Response data:", response.data);

        if (response.data?.data?.cook_time) {
            console.log("Cook time:", response.data.data.cook_time);
        }

        return response.data;
    } catch (err: any) {
        console.error("Network Error Details:");
        console.error("- Error message:", err.message);
        console.error("- Error code:", err.code);
        console.error("- Response status:", err.response?.status);
        console.error("- Response data:", err.response?.data);

        // Provide more specific error messages for debugging
        if (err.code === 'NETWORK_ERROR' || err.code === 'ECONNREFUSED') {
            console.error("Network connection failed - check if API server is running");
        }

        throw err;
    }
}

// Function to fetch recipe data with error handling and retries
export async function fetchRecipeData(params: RecipeParams): Promise<any> {
    try {
        const response = await apiClient.post("", params);
        return response.data;
    } catch (error) {
        console.error("Error fetching recipe data:", error);
        throw new Error("Failed to fetch recipe data. Please try again later.");
    }
}

import axios from 'axios';
import Constants from 'expo-constants';

// Use environment-specific endpoints
const getApiEndpoint = () => {
  // Check if running in development vs production
  if (__DEV__) {
    return "http://15.235.185.245/recipe/";
  } else {
    // For production builds, use HTTPS or a more reliable endpoint
    return "https://15.235.185.245/recipe/";
  }
};

const endpoint = getApiEndpoint();

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

// Configure axios for better APK compatibility
const apiClient = axios.create({
    baseURL: endpoint,
    timeout: 30000, // 30 second timeout
    headers: headers,
    // Add retry configuration for better reliability
    validateStatus: function (status) {
        return status >= 200 && status < 300;
    }
});

// Add request interceptor for debugging
apiClient.interceptors.request.use(
    (config) => {
        console.log("API Request:", {
            url: config.url,
            baseURL: config.baseURL,
            method: config.method,
            data: config.data
        });
        return config;
    },
    (error) => {
        console.error("Request interceptor error:", error);
        return Promise.reject(error);
    }
);

// Add response interceptor for debugging
apiClient.interceptors.response.use(
    (response) => {
        console.log("API Response:", {
            status: response.status,
            data: response.data
        });
        return response;
    },
    (error) => {
        console.error("Response interceptor error:", {
            message: error.message,
            status: error.response?.status,
            data: error.response?.data
        });
        return Promise.reject(error);
    }
);

interface RecipeParams {
    diet: string;
    type: string;
    difficulty: string;
    ingredients: string;
}

export async function generateRecipe(params: RecipeParams) {
    try {
        console.log("Environment:", __DEV__ ? "development" : "production");
        console.log("API Endpoint:", endpoint);
        console.log("Sending request to:", endpoint);
        console.log("Request params:", params);

        const response = await apiClient.post("", params);

        console.log("Response received:", response.status);
        console.log("Response data:", response.data);

        if (response.data?.data?.cook_time) {
            console.log("Cook time:", response.data.data.cook_time);
        }

        return response.data;
    } catch (err: any) {
        console.error("Network Error Details:");
        console.error("- Error message:", err.message);
        console.error("- Error code:", err.code);
        console.error("- Response status:", err.response?.status);
        console.error("- Response data:", err.response?.data);
        console.error("- Network state:", err.isNetworkError);

        // Provide more specific error messages for debugging
        if (err.code === 'NETWORK_ERROR' || err.code === 'ECONNREFUSED') {
            console.error("Network connection failed - check if API server is running");
            throw new Error("Unable to connect to recipe service. Please check your internet connection and try again.");
        }

        if (err.code === 'TIMEOUT') {
            throw new Error("Request timed out. Please try again.");
        }

        if (err.response?.status === 404) {
            throw new Error("Recipe service not found. Please try again later.");
        }

        if (err.response?.status >= 500) {
            throw new Error("Server error. Please try again later.");
        }

        throw err;
    }
}

// Function to fetch recipe data with error handling and retries
export async function fetchRecipeData(params: RecipeParams): Promise<any> {
    try {
        const response = await apiClient.post("", params);
        return response.data;
    } catch (error) {
        console.error("Error fetching recipe data:", error);
        throw new Error("Failed to fetch recipe data. Please try again later.");
    }
}
